// Requirement 3: hashes are prepared off-state. State assignment occurs only in atomic commits.
async function generateRecoveryCodeSet(): Promise<{ codes: string[]; entries: RecoveryEntry[] }> {
  const codes: string[] = [];
  const entries: RecoveryEntry[] = [];
  for (let i = 0; i < 8; i++) {
