          return error(request, nonce, 500);
        } finally {
          record.recoveryReserved = false;
        }
      }
      return error(request, nonce, 404);
    } catch {
      // Requirement 2: generic production failure only; no stack trace or sensitive output.
      return error(request, nonce, 500);
    }
  },
