type MfaRecord = {
  accountId: string;
  enrolled: boolean;
  encryptedAuthenticatorSecret: string;
  recoveryCodes: RecoveryEntry[];
  recoveryAttempts: number;
  recoveryLockedUntil: number;
  recoveryReserved: boolean;
  enrolledAt: number;
