const sessions = new Map<string, Session>();
// Task: MFA state belongs to the authenticated account, never to a transient session.
const mfaRecords = new Map<string, MfaRecord>();

const keyBytes = randomBytes(32);
const encryptionKeyPromise = crypto.subtle.importKey("raw", keyBytes, { name: "AES-GCM" }, false, ["encrypt", "decrypt"]);
