  const out: number[] = [];
  for (const char of value) {
    const n = alphabet.indexOf(char);
    if (n < 0) return null;
    buffer = (buffer << 5) | n;
    bits += 5;
    while (bits >= 8) {
      bits -= 8;
      out.push((buffer >> bits) & 255);
    }
  }
